INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 13, 'theory', 'TLS and HTTPS: Encryption, Certificates and Trust');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 13, 0, 'What is asymmetric cryptography used for in TLS?', '["Encrypting the whole data stream", "Signing and key exchange during the handshake, to get a shared symmetric secret", "Compressing data", "DNS queries"]', 1, 'Asymmetric cryptography is slow, so it is used only to agree on a secret; the data itself is encrypted quickly with symmetric keys.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 13, 1, 'A client opens https://www.example.org, but the certificate only covers example.org. What happens?', '["The connection is made with no warnings", "The browser substitutes the right name", "The server automatically reissues the certificate", "The browser refuses: the name does not match the SAN"]', 3, 'The address must match one of the names in the certificate (the SAN field).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 13, 2, 'A site''s certificate opens fine for the administrator, but some clients get "unable to build the chain". What is the likely cause?', '["The server does not send the intermediate certificate", "The root certificate has expired", "Port 443 is closed", "DNS is stale"]', 0, 'Some clients will rebuild the chain on their own, while others will refuse: the server must send the intermediates.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 13, 3, 'What does forward secrecy give you?', '["It speeds up the handshake", "It hides the site name", "Stealing the private key later does not let anyone decrypt previously recorded traffic", "It lets you skip certificate checks"]', 2, 'Each session uses a fresh secret, and the long-term key only signs the handshake.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 13, 4, 'How many round trips (RTT) does the TLS 1.3 handshake take after TCP?', '["Two", "One", "Three", "Zero, always"]', 1, 'TLS 1.3 takes one round trip; TLS 1.2 takes two.');
